	// for each letter of the alphabet
	for (int i = 0; i < 26; i++) {
		morseCode.put(String.valueOf((char)('a' + i)),
						   getMorseCode((char)('a' + i)));
	}

	// Iterate through the input words and count the unique
	// combinations of Morse code values
	Set<String> uniqueValues = new HashSet<String>();
	for (String word : words) {
		StringBuilder morseWord = new StringBuilder();
		for (char c : word.toCharArray()) {
			morseWord.append(morseCode.get(String.valueOf(c)));
		}
		if (!uniqueValues.contains(morseWord.toString())) {
			uniqueValues.add(morseWord.toString());
			uniqueCount++;
		}
	}
	return uniqueCount;
}

