private static boolean isPerfectSquare(int num) {
  int sqrt = (int) Math.sqrt(num);
  return num == sqrt * sqrt;
}

private static void swap(int[] arr, int i, int j) {
  int temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}

private static String arrayToString(int[] arr) {
